def bounded_box(points: list[tuple[float, float, float]], padding: float = 12.0) -> tuple[float, float, float]:
    if not points:
        return (22.0, 22.0, 22.0)
    xs, ys, zs = zip(*points)
    return (
        min(30.0, max(18.0, max(xs) - min(xs) + padding)),
        min(30.0, max(18.0, max(ys) - min(ys) + padding)),
        min(30.0, max(18.0, max(zs) - min(zs) + padding)),
    )


def parse_target_features(path: Path) -> TargetFeatures:
    if not path.is_file():
        return TargetFeatures(False, 0, 0, 0, 0.5, 0.3, 0.2, 25.0)

    hydrophobic = {"ALA", "VAL", "LEU", "ILE", "MET", "PRO", "PHE", "TRP"}
    polar = {"SER", "THR", "ASN", "GLN", "TYR", "CYS", "HIS", "LYS", "ARG", "ASP", "GLU"}
    aromatic = {"PHE", "TYR", "TRP", "HIS"}
    positive = {"LYS", "ARG", "HIS"}
    negative = {"ASP", "GLU"}
    ignored_het = {"HOH", "WAT", "DOD", "NA", "K", "CL", "CA", "MG", "ZN", "MN", "SO4", "PO4"}
    residues: set[tuple[str, str, str]] = set()
    residue_coords: dict[tuple[str, str, str], list[tuple[float, float, float]]] = {}
    coords = []
    hetatm_coords = []

    with path.open(errors="ignore") as handle:
        for line in handle:
            if not line.startswith(("ATOM", "HETATM")):
                continue
            resn = line[17:20].strip().upper()
            chain = line[21:22].strip()
            resid = line[22:26].strip()
            try:
                coord = (
                    float(line[30:38]),
                    float(line[38:46]),
                    float(line[46:54]),
                )
            except ValueError:
                continue
            if line.startswith("ATOM"):
                key = (chain, resid, resn)
                residues.add(key)
                residue_coords.setdefault(key, []).append(coord)
                coords.append(coord)
            elif resn not in ignored_het:
                hetatm_coords.append(coord)

    residue_names = [resn for _, _, resn in residues]
    residue_count = max(1, len(residue_names))
    atom_count = len(coords)
    hydrophobic_ratio = sum(r in hydrophobic for r in residue_names) / residue_count
    polar_ratio = sum(r in polar for r in residue_names) / residue_count
    aromatic_ratio = sum(r in aromatic for r in residue_names) / residue_count
    positive_ratio = sum(r in positive for r in residue_names) / residue_count
    negative_ratio = sum(r in negative for r in residue_names) / residue_count
    charge_balance = positive_ratio - negative_ratio
    if coords:
        xs, ys, zs = zip(*coords)
        span = ((max(xs) - min(xs)) + (max(ys) - min(ys)) + (max(zs) - min(zs))) / 3.0
    else:
        span = 25.0
    if len(hetatm_coords) >= 3:
        pocket_center = mean_coord(hetatm_coords)
        pocket_box = bounded_box(hetatm_coords, padding=14.0)
        pocket_confidence = 1.0
    elif residue_coords and coords:
        protein_center = mean_coord(coords)
        scored_residues = []
        for key, points in residue_coords.items():
            resn = key[2]
            center = mean_coord(points)
            distance = coord_distance(center, protein_center)
            residue_score = (
                (3.0 if resn in aromatic else 0.0)
                + (2.0 if resn in hydrophobic else 0.0)
                + (0.8 if resn in polar else 0.0)
                - 0.025 * distance
            )
            scored_residues.append((residue_score, center, points))
        top_n = min(len(scored_residues), max(8, min(28, len(scored_residues) // 8 or 8)))
        top = sorted(scored_residues, key=lambda item: item[0], reverse=True)[:top_n]
        pocket_points = [point for _, _, points in top for point in points]
        pocket_center = mean_coord([center for _, center, _ in top])
        pocket_box = bounded_box(pocket_points, padding=12.0)
        pocket_confidence = min(0.85, 0.2 + top_n / max(1, len(scored_residues)))
    else:
        pocket_center = (0.0, 0.0, 0.0)
        pocket_box = (22.0, 22.0, 22.0)
        pocket_confidence = 0.0

    return TargetFeatures(
        True,
        target_signature(path),
        atom_count,
        len(residue_names),
        hydrophobic_ratio,
        polar_ratio,
        aromatic_ratio,
        span,
        positive_ratio,
        negative_ratio,
        charge_balance,
        pocket_center,
        pocket_box,
        pocket_confidence,
    )


def canonicalize(smiles: str, Chem) -> str | None:
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return None
    return Chem.MolToSmiles(mol)


def reagent_has_handle(smiles: str, kind: str, Chem) -> bool:
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return False
    if kind == "amine":
        return mol.HasSubstructMatch(Chem.MolFromSmarts("[NH2]")) and any(
            atom.GetSymbol() == "Br" for atom in mol.GetAtoms()
        )
    if kind == "boronic":
        return mol.HasSubstructMatch(Chem.MolFromSmarts("[B]([OH])[OH]"))
    if kind == "acyl":
        return mol.HasSubstructMatch(Chem.MolFromSmarts("[C](=O)Cl"))
    return False


def reagent_score(smiles: str, kind: str, features: TargetFeatures, Chem, Descriptors) -> float:
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return -1e9
    mw = float(Descriptors.MolWt(mol))
    halogens = smiles.count("F") + smiles.count("Cl")
    aromatic_atoms = smiles.count("c")
    hetero_atoms = sum(smiles.count(atom) for atom in ["n", "N", "O"])
    handle_bonus = {"amine": 60.0, "boronic": 40.0, "acyl": 45.0}[kind]
    if kind == "boronic":
        target_mw = 180.0 + 95.0 * features.hydrophobic_ratio + 45.0 * features.aromatic_ratio
        size_term = -0.26 * abs(mw - target_mw)
    elif kind == "acyl":
        target_mw = 205.0 + 70.0 * features.hydrophobic_ratio + 25.0 * features.aromatic_ratio
        size_term = -0.30 * abs(mw - target_mw)
    else:
        target_mw = 250.0 + 75.0 * features.hydrophobic_ratio
        size_term = -0.12 * abs(mw - target_mw)
    return (
        handle_bonus
        + mw * 0.08
        + size_term
        + halogens * (8.0 + 6.0 * features.aromatic_ratio)
        + aromatic_atoms * (0.9 + 1.2 * features.hydrophobic_ratio)
        + hetero_atoms * (1.0 + 3.0 * features.polar_ratio)
    )


def mutation_specs(features: TargetFeatures) -> list[tuple[str, str]]:
    specs = [
        ("F", "[cH:1]>>[c:1]F"),
        ("Cl", "[cH:1]>>[c:1]Cl"),
        ("Me", "[cH:1]>>[c:1]C"),
    ]
    if features.hydrophobic_ratio >= 0.35 or features.aromatic_ratio >= 0.12:
        specs.append(("OMe", "[cH:1]>>[c:1]OC"))
    if features.polar_ratio >= features.hydrophobic_ratio:
        specs.append(("CN", "[cH:1]>>[c:1]C#N"))
    return specs


def expand_reagents(
    seeds: list[str],
    kind: str,
    features: TargetFeatures,
    Chem,
    AllChem,
    Descriptors,
    max_total: int,
) -> list[Reagent]:
    seen: dict[str, Reagent] = {}
    for seed in seeds:
        can = canonicalize(seed, Chem)
        if can and reagent_has_handle(can, kind, Chem):
            seen[can] = Reagent(can, 0, "seed")

    for seed in list(seen):
        mol = Chem.MolFromSmiles(seed)
        if mol is None:
            continue
        for label, smarts in mutation_specs(features):
            try:
                rxn = AllChem.ReactionFromSmarts(smarts)
                products = rxn.RunReactants((mol,))
            except Exception:
                continue
            variants = []
            for product_set in products[:24]:
                product = product_set[0]
                try:
                    Chem.SanitizeMol(product)
                except Exception:
                    continue
                smiles = Chem.MolToSmiles(product)
                if smiles in seen or not reagent_has_handle(smiles, kind, Chem):
                    continue
                pmol = Chem.MolFromSmiles(smiles)
                if pmol is None:
                    continue
                mw = float(Descriptors.MolWt(pmol))
                if kind != "acyl" and mw > 430:
                    continue
                if kind == "acyl" and mw > 360:
                    continue
                variants.append(smiles)
            variants = sorted(
                set(variants),
                key=lambda s: (-reagent_score(s, kind, features, Chem, Descriptors), s),
            )
            for smiles in variants[:2]:
                seen[smiles] = Reagent(smiles, 1, f"{label}_runtime")

    ranked = sorted(
        seen.values(),
        key=lambda r: (r.depth, -reagent_score(r.smiles, kind, features, Chem, Descriptors), r.smiles),
    )
    return ranked[:max_total]


