#!/usr/bin/env python3
from __future__ import annotations

import csv
import json
from pathlib import Path
from urllib.request import urlopen


def fetch_json(url: str) -> dict:
    with urlopen(url, timeout=20) as response:
        return json.loads(response.read().decode("utf-8"))


def entry_summary(pdb_id: str) -> dict[str, object]:
    entry_url = f"https://data.rcsb.org/rest/v1/core/entry/{pdb_id}"
    nonpoly_url = f"https://data.rcsb.org/rest/v1/core/nonpolymer_entity/{pdb_id}/1"
    entry = fetch_json(entry_url)
    try:
        nonpoly = fetch_json(nonpoly_url)
    except Exception:
        nonpoly = {}
    citation = (entry.get("citation") or [{}])[0]
    struct = entry.get("struct") or {}
    keywords = entry.get("struct_keywords") or {}
    exptl = (entry.get("exptl") or [{}])[0]
    chem = (nonpoly.get("pdbx_entity_nonpoly") or {})
    return {
        "pdb_id": pdb_id,
        "entry_url": entry_url,
        "title": struct.get("title"),
        "classification": keywords.get("pdbx_keywords"),
        "method": exptl.get("method"),
        "citation_title": citation.get("title"),
        "nonpolymer_entity_1": {
            "chem_comp_id": chem.get("comp_id"),
            "name": chem.get("name"),
        },
    }


def main() -> int:
    manifest = list(csv.DictReader(Path("/saisdata/manifest.csv").open()))
    summaries = [entry_summary(row["pdb_id"]) for row in manifest]
    out = Path("experiments/public_target_summaries.json")
    out.write_text(json.dumps(summaries, indent=2, sort_keys=True) + "\n")
    print(json.dumps(
        [
            {
                "pdb_id": row["pdb_id"],
                "classification": row["classification"],
                "method": row["method"],
                "nonpolymer_entity_1": row["nonpolymer_entity_1"],
                "entry_url": row["entry_url"],
            }
            for row in summaries
        ],
        indent=2,
        sort_keys=True,
    ))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

